{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.unicommerce_fact_items_intermediate as (select MARKETPLACE ,MARKETPLACE_MAPPED ,SOURCE ,ORDER_ID ,ORDER_NAME ,FULFILLMENT_TAT ,UC_CREATED ,SHIPPING_LAST_UPDATE_DATE ,SHIPPING_LAST_UPDATE_TIMESTAMP ,SKU ,SKU_GROUP ,PRODUCT_ID ,PRODUCT_NAME ,SALE_ORDER_ITEM_STATUS ,ITEM_DETAILS ,CURRENCY ,ADDRESS_LINE_1 ,ADDRESS_LINE_2 ,CITY ,STATE ,COUNTRY ,PINCODE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,SHIPPING_PRICE ,SUBORDER_QUANTITY::integer as SUBORDER_QUANTITY ,SHIPPING_QUANTITY::integer as SHIPPING_QUANTITY ,DISCOUNT::float as DISCOUNT ,TRY_CAST(TAX as float) as TAX ,SELLING_PRICE ,SHIPPINGPACKAGECODE ,SHIPPINGPACKAGESTATUS ,WAREHOUSE_NAME ,SALEORDERITEMCODE ,MRP::float as MRP ,COURIER ,SHIPPING_COURIER ,SHIPPING_STATUS ,CREATED_TIMESTAMP ,PICKING_TIMESTAMP ,PICKED_TIMESTAMP ,PACKED_TIMESTAMP ,MANIFESTED_TIMESTAMP ,DISPATCHED_TIMESTAMP ,DISPATCH_DATE ,DELIVERED_DATE ,DELIVERED_TIMESTAMP ,try_Cast(RETURN_DATE as date) AS RETURN_DATE ,DAYS_TO_DISPATCH ,AWB ,RETURN_FLAG ,RETURN_QUANTITY ,CANCELLED_QUANTITY ,NEW_CUSTOMER_FLAG ,ACQUISITION_PRODUCT ,DAYS_IN_SHIPMENT ,DISPATCH_TO_DELIVERY_DAYS ,INVOICE_DATE ,COST ,CATEGORY ,PRODUCT_NAME_SHOPIFY ,PLA_SPENDS ,BANNER_SPENDS ,SALES_TARGET ,SPENDS_TARGET from snitch_db.maplemonk.unicommerce_fact_items_intermediate_old where order_date::date <= \'2024-12-15\' ) UNION ALL ( select MARKETPLACE , CASE WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%CRED%\' THEN \'CRED\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%FLIPKART%\' THEN \'FLIPKART\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%MYNTRA%\' and upper(trim(marketplace)) not like \'%SJIT%\' THEN \'MYNTRA\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%AJIO%\' THEN \'AJIO\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%AMAZON%\' THEN \'AMAZON\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%DONOSHOP%\' THEN \'POPCLUB\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%NYKAA_FASHION%\' THEN \'NYKAA_FASHION\' WHEN UPPER(TRIM(MARKETPLACE)) LIKE \'%NYKAA_COM%\' THEN \'NYKAA.COM\' ELSE MARKETPLACE END AS MARKETPLACE_MAPPED ,null as SOURCE ,ORDER_ID ,ORDER_NAME ,FULFILLMENT_TAT::timestamp ,UC_CREATED ,SHIPPING_LAST_UPDATE_DATE ,SHIPPING_LAST_UPDATE_TIMESTAMP ,SKU ,SKU_GROUP ,PRODUCT_ID ,null as PRODUCT_NAME ,SALE_ORDER_ITEM_STATUS ,ITEM_DETAILS ,null as CURRENCY ,ADDRESS_LINE_1 ,ADDRESS_LINE_2 ,CITY ,STATE ,COUNTRY ,PINCODE ,ORDER_STATUS ,ORDER_DATE ,ORDER_TIMESTAMP ,null as SHIPPING_PRICE ,1 as SUBORDER_QUANTITY ,1 as SHIPPING_QUANTITY ,DISCOUNT::float ,TRY_CAST(TAX as float) as TAX ,SELLING_PRICE ,SHIPPINGPACKAGECODE ,SHIPPINGPACKAGESTATUS ,WAREHOUSE_NAME ,SALEORDERITEMCODE ,MRP::float ,COURIER ,SHIPPING_COURIER ,SHIPPING_STATUS ,CREATED_TIMESTAMP ,null as PICKING_TIMESTAMP ,null as PICKED_TIMESTAMP ,PACKED_TIMESTAMP ,null as MANIFESTED_TIMESTAMP ,DISPATCHED_TIMESTAMP ,DISPATCH_DATE ,DELIVERED_DATE ,DELIVERED_TIMESTAMP ,RETURN_DATE ,null as DAYS_TO_DISPATCH ,AWB ,null as RETURN_FLAG ,null as RETURN_QUANTITY ,null as CANCELLED_QUANTITY ,null as NEW_CUSTOMER_FLAG ,null as ACQUISITION_PRODUCT ,null as DAYS_IN_SHIPMENT ,null as DISPATCH_TO_DELIVERY_DAYS ,INVOICE_DATE ,COST::float ,CATEGORY ,null as PRODUCT_NAME_SHOPIFY ,null as PLA_SPENDS ,null as BANNER_SPENDS ,null as SALES_TARGET ,null as SPENDS_TARGET from snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where order_date::date > \'2024-12-15\' and not(lower(order_name) in ( select distinct lower(order_name) from snitch_db.maplemonk.unicommerce_fact_items_intermediate_old where order_date::date <= \'2024-12-15\' )) ); create or replace table snitch_db.maplemonk.pincode_precentiles as select pincode, marketplace_mapped, shipping_courier, dispatch_to_delivery_days, orders, share, 50 as percentile from ( select *, row_number() over (partition by pincode, marketplace_mapped, shipping_courier order by share) rw from (select *, div0(SUM(orders) OVER (PARTITION BY pincode, shipping_courier,marketplace_mapped ORDER BY dispatch_to_delivery_days ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), sum(orders) over (partition by pincode,marketplace_mapped, shipping_courier)) share from (select pincode, dispatch_to_delivery_days,marketplace_mapped, shipping_courier, count(distinct order_id) orders from snitch_db.maplemonk.unicommerce_fact_items_intermediate where dispatch_Date is not null and delivered_Date is not null and order_status <> \'CANCELLED\' group by 1,2,3,4 ) ) where share > 0.5 ) where rw = 1 union all select pincode, marketplace_mapped, shipping_courier, dispatch_to_delivery_days, orders, share, 90 as percentile from ( select *, row_number() over (partition by pincode,marketplace_mapped, shipping_courier order by share) rw from (select *, div0(SUM(orders) OVER (PARTITION BY pincode,marketplace_mapped, shipping_courier ORDER BY dispatch_to_delivery_days ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), sum(orders) over (partition by pincode,marketplace_mapped, shipping_courier)) share from (select pincode, marketplace_mapped,shipping_courier, dispatch_to_delivery_days, count(distinct order_id) orders from snitch_db.maplemonk.unicommerce_fact_items_intermediate where dispatch_Date is not null and delivered_Date is not null and order_status <> \'CANCELLED\' group by 1,2,3,4 ) ) where share > 0.9 ) where rw = 1 ; create or replace table snitch_db.maplemonk.customerID_test as with new_phone_numbers as ( select contact_num ,9700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num from snitch_db.maplemonk.unicommerce_fact_items_intermediate ) a ), int as ( select contact_num,email,coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email,maple_monk_id,9800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email,maple_monk_id from ( select phone as contact_num,email from snitch_db.maplemonk.unicommerce_fact_items_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num,email,case when email is not null and email <> \'\' then min(maple_monk_id) over (partition by email ) else maple_monk_id end maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table snitch_db.maplemonk.unicommerce_fact_items_snitch as select distinct coalesce(c.maple_monk_id,c.maple_monk_id) customer_id, o.*, min(order_date) over(partition by customer_id) as acquisition_date, d.dispatch_to_delivery_days dispatch_to_delivery_days_50th_percentile, e.dispatch_to_delivery_days dispatch_to_delivery_days_90th_percentile, AM.SKU_CLASS, TM.CITY_TIER, fic.phoneno shopify_name, fic.email shopify_email, fic.customer_id shopify_customer_id, lm. product_type, lm.occassion, lm.print_design, lm.collar, lm.material, lm.sleeve_type, lm.fit, lm.color, from snitch_db.maplemonk.unicommerce_fact_items_intermediate o left join (select * from ( select order_name, phone phoneno,email, customer_id, row_number() over (partition by ordeR_name order by phone) rw from snitch_db.maplemonk.facT_items_snitch ) where rw=1 ) fic on fic.ordeR_name = o.ordeR_name left join (select distinct contact_num phone,maple_monk_id from snitch_db.maplemonk.customerID_test )c on c.phone = o.phone left join snitch_db.maplemonk.pincode_precentiles d on o.pincode = d.pincode and o.marketplace_mapped = d.marketplace_mapped and o.shipping_courier = d.shipping_courier and d.percentile = 50 left join snitch_db.maplemonk.pincode_precentiles e on o.pincode = e.pincode and o.marketplace_mapped = e.marketplace_mapped and o.shipping_courier = e.shipping_courier and e.percentile = 90 left join (select * from (select *,row_number() over(partition by sku_group order by 1)rw from snitch_db.maplemonk.AVAILABILITY_MASTER_V2) where rw=1) AM on AM.sku_group = o.sku_group left join (select * from (select *,row_number() over(partition by delivery_postcode order by 1)rw from snitch_db.maplemonk.pincodemappingzoneupdatedsnitch)where rw=1) TM on o.pincode = TM.delivery_postcode left join (Select * from ( SELECT trim(sku_group) as sku_group, CATEGORY as product_type, occassion_new as occassion, designs as print_design, collar_new as collar, material_new as material, sleeve_type, fit, color, row_number() over(partition by sku_group order by 1)rw from snitch_db.maplemonk.metafields_data ) where rw =1) lm on o.sku_group = lm.sku_group ; create or replace table snitch_db.maplemonk.best_courier_by_pincode as select a.pincode, best_shipping_courier, \"50th\", \"90th\",b.orders from (select pincode, best_shipping_courier, \"50th\", \"90th\" from ( select *, row_number() over (partition by pincode order by \"50th\" asc, \"90th\" asc) rw from ( select pincode, shipping_courier best_shipping_courier, max(dispatch_to_delivery_days_50th_percentile) as \"50th\", max(dispatch_to_delivery_days_90th_percentile) \"90th\", count(distinct order_id) orders from ( snitch_db.maplemonk.unicommerce_fact_items_snitch ) where lower(marketplace_mapped) like \'%shopify%\' group by 1,2 )where orders>20)where rw = 1)a left join (select pincode, count(distinct order_id) orders from snitch_db.maplemonk.unicommerce_fact_items_snitch where lower(marketplace_mapped) like \'%shopify%\' group by 1) b on a.pincode = b.pincode ;",
                    "transaction": true
                }
            ) }}
